/**
 * El cruce. Compara lo que dice la planilla contra quién está adentro de Skool
 * y devuelve tres listas, no dos.
 *
 * La tercera —«revisar»— existe por el §4 del doc 24: ella paga con la cuenta
 * de MercadoPago que tiene a mano (la del marido, la de la madre) pero se crea
 * el usuario de Skool con su correo personal. Si el cruce fuera sólo por email,
 * esas filas caerían en «sacar» y terminaríamos echando a alguien que paga.
 * Por eso lo que no matchea NO se saca: se mira a ojo.
 *
 * Nada de esto ejecuta nada sobre Skool. Skool no tiene API pública en el plan
 * Hobby: este flujo arma el listado y una persona lo aplica.
 */
const cfg = $('Configuración').first().json;
const HORAS_REPESCA = Number(cfg.horasParaRepescar) || 48;
const DIAS_PACK = Number(cfg.diasDelPack) || 90;

const norm = (x) => String(x ?? '').trim().toLowerCase();
const limpio = (x) => String(x ?? '').trim();
const ahora = Date.now();
const dias = (ms) => Math.floor(ms / 86400000);

const miembros = $input.all()
  .map((i) => i.json)
  .filter((m) => norm(m.email));

const ventas = $('Leer las ventas').all()
  .map((i) => i.json)
  .filter((v) => norm(v.email));

/* Una misma persona puede tener varias filas: se dio de baja y volvió, o compró
   el pack después del mensual. Vale la más nueva. */
const ultimaVenta = new Map();
for (const v of ventas) {
  const clave = norm(v.email);
  const previa = ultimaVenta.get(clave);
  const fecha = Date.parse(limpio(v.fecha)) || 0;
  if (!previa || fecha >= previa._fecha) {
    ultimaVenta.set(clave, { ...v, _fecha: fecha });
  }
}

/**
 * Cuándo se le vence el acceso.
 *
 * El plan mensual no vence: se renueva solo hasta que cancela. El pack sí, pero
 * hoy NADIE escribe `acceso_vence` —ni el checkout ni el webhook—, así que si la
 * columna viene vacía se calcula acá desde la fecha de compra. Es un parche: lo
 * correcto es que lo escriba el webhook al confirmar el pago del pack.
 */
function venceEl(v) {
  const declarado = Date.parse(limpio(v.acceso_vence));
  if (declarado) return declarado;
  if (norm(v.plan).includes('trimestral') && v._fecha) {
    return v._fecha + DIAS_PACK * 86400000;
  }
  return null;
}

const sacar = [];
const revisar = [];

for (const m of miembros) {
  const v = ultimaVenta.get(norm(m.email));

  if (!v) {
    revisar.push({
      email: limpio(m.email),
      nombre: limpio(m.nombre),
      motivo: 'Está en Skool y no hay ninguna venta con ese email. Puede ser que haya pagado con otro correo, o que la hayas invitado vos a mano.',
    });
    continue;
  }

  const estado = norm(v.estado);
  const suscripcion = norm(v.estado_suscripcion);
  const vence = venceEl(v);

  if (estado === 'cancelado' || suscripcion === 'cancelled') {
    sacar.push({
      email: limpio(v.email),
      nombre: limpio(v.nombre) || limpio(m.nombre),
      motivo: 'Canceló la suscripción.',
    });
  } else if (vence && vence < ahora) {
    sacar.push({
      email: limpio(v.email),
      nombre: limpio(v.nombre) || limpio(m.nombre),
      motivo: `Se le venció el acceso del pack hace ${dias(ahora - vence)} días.`,
    });
  } else if (estado === 'cobro_rechazado') {
    revisar.push({
      email: limpio(v.email),
      nombre: limpio(v.nombre) || limpio(m.nombre),
      motivo: 'MercadoPago le rechazó el último cobro. Todavía no la saques: puede que se destrabe sola con el reintento.',
    });
  }
}

/* Repescar: pagó, se le mandó la invitación y no la aceptó. El corte de horas
   evita levantar a la que compró hace veinte minutos. */
const enSkool = new Set(miembros.map((m) => norm(m.email)));
const repescar = [];

for (const v of ultimaVenta.values()) {
  if (norm(v.estado) !== 'pagado') continue;
  if (enSkool.has(norm(v.email))) continue;
  if (norm(v.acceso_skool) === 'no') continue;

  const horas = v._fecha ? (ahora - v._fecha) / 3600000 : Infinity;
  if (horas < HORAS_REPESCA) continue;

  repescar.push({
    email: limpio(v.email),
    nombre: limpio(v.nombre),
    motivo: `Pagó hace ${dias(ahora - v._fecha)} días y todavía no entró a Skool.`,
  });
}

return [{
  json: {
    sacar,
    repescar,
    revisar,
    totales: {
      miembrosSkool: miembros.length,
      ventasVivas: ultimaVenta.size,
      sacar: sacar.length,
      repescar: repescar.length,
      revisar: revisar.length,
    },
  },
}];

/**
 * Arma el email. Sale todas las semanas aunque no haya nada que hacer: el
 * silencio no se distingue de un flujo roto, y la semana que este informe deje
 * de llegar tiene que notarse.
 */
const d = $input.first().json;
const hoy = new Date().toLocaleDateString('es-AR', { day: '2-digit', month: '2-digit', year: 'numeric' });

const bloque = (titulo, bajada, filas) => {
  if (!filas.length) return '';
  const items = filas.map((f) => {
    const quien = f.nombre ? `<strong>${f.nombre}</strong> (${f.email})` : `<strong>${f.email}</strong>`;
    return `<li>${quien} — ${f.motivo}</li>`;
  }).join('\n');
  return `<h3>${titulo} (${filas.length})</h3>\n<p>${bajada}</p>\n<ul>\n${items}\n</ul>`;
};

const partes = [
  bloque('Sacar de Skool', 'Ya no están pagando. Quitalas de la comunidad.', d.sacar),
  bloque('Volver a invitar', 'Pagaron y nunca aceptaron la invitación. Reenviales el link.', d.repescar),
  bloque('Revisar a ojo', 'No las toques sin mirar primero: casi siempre es que el email de Skool no es el mismo con el que pagó.', d.revisar),
].filter(Boolean);

const cuerpo = partes.length
  ? partes.join('\n<hr>\n')
  : '<p>Ninguna baja pendiente, ninguna invitación colgada y nada raro para revisar. No hay que hacer nada esta semana.</p>';

const html = `
<p>Conciliación del ${hoy}.</p>
<p>${d.totales.miembrosSkool} miembros en Skool contra ${d.totales.ventasVivas} personas en la planilla.</p>
<hr>
${cuerpo}
<hr>
<p style="font-size:13px;color:#666">La lista de miembros de Skool sale de la pestaña <strong>skool_miembros</strong> de la planilla. Si no la actualizaste esta semana, este informe está mirando la foto vieja.</p>
`.trim();

const pendientes = d.totales.sacar + d.totales.repescar + d.totales.revisar;
const asunto = pendientes
  ? `Conciliación semanal: ${pendientes} cosas para resolver`
  : 'Conciliación semanal: nada que hacer';

return [{ json: { ...d, asuntoEmail: asunto, cuerpoEmail: html } }];

